/*
Day #11/24: Midpoint Polygon
https://openprocessing.org/sketch/2393826
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let S, pts;

function setup() {
  createCanvas(windowWidth, windowHeight);
	frameRate(60);
	background(0, 0, 8);
	describe("rotating n-point distorted circle with recursive midpoint polygons fading from cyan to purple");

  noFill();
  strokeWeight(2);
	S = max(width, height);

	const num = ~~random(6, 11);
	pts = [];
	const da = (TWO_PI/num) * 0.2;
	for (let i = 0; i < num; i++) {
		const a = i/num*TWO_PI+random(-da, da);
		const l = random(S*0.1, S*0.6);
		const x = cos(a) * l;
		const y = sin(a) * l;
		pts[i] = {x, y};
	}
	loop();
}

function draw() {
	background("rgba(0, 0, 8, 0.1)");
	translate(width/2, height/2);
	rotate(frameCount/60)

	let tmp1 = copyPtsArr(pts);
	var num = pts.length * 2;
	for (let i = 0; i < num; i++) {
		stroke(lerpColor(color("cyan"), color("rgba(128,0,128,0.3)"), i/(num-1)));
		beginShape();
		let tmp2 = [];
		for (let i = 0; i < tmp1.length; i++) {
			vertex(tmp1[i].x, tmp1[i].y);
			const f = 0.5+sin(frameCount/30)*0.2; // (sin(TWO_PI*((frameCount+i)%60)/60)+1)/2;
			tmp2[i] = {
				x: lerp(tmp1[i].x,tmp1[(i+1)%tmp1.length].x, f),
				y: lerp(tmp1[i].y,tmp1[(i+1)%tmp1.length].y, f),
			}
		}
		endShape(CLOSE);

		tmp1 = copyPtsArr(tmp2);
	}
}

function copyPtsArr(pts) {
	let tmp = [];
	for (let i = 0; i < pts.length; i++) tmp[i] = {x: pts[i].x, y: pts[i].y}
	return tmp;
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
